<template>
  <div class="px-12 sub-header flex items-center" style="padding: 13px 12px">
    <q-icon
      v-if="!route.fullPath.includes('/share')"
      color="white"
      name="arrow_back_ios"
      @click="$router.push('/asn_shipment/dashboard')"
    />
    <span> &nbsp;{{ $t('advance_ship_notice') }}</span>
  </div>
  <div class="px-10 row text-bold">
    <q-stepper
      v-model="step"
      header-nav
      header-class="no-wrap"
      class="no-border shadow-0 full-width"
      ref="stepper"
      alternative-labels
      done-icon="none"
      line
      active-icon="none"
      done-color="primary"
      active-color="primary"
      content="none"
    >
      <q-step
        :name="1"
        :title="$t('ordered')"
        :done="
          props.data.status == 'Reserved' ||
          props.data.status == 'Allocated' ||
          props.data.status == 'Picking list printed' ||
          props.data.status == 'Delivered' ||
          props.data.status == 'Invoiced'
        "
        hidden
      >
      </q-step>

      <q-step
        :name="3"
        :title="$t('in_delivery')"
        :done="
          props.data.status == 'Delivered' || props.data.status == 'Invoiced'
        "
        hidden
      >
      </q-step>

      <q-step
        :name="4"
        :title="$t('delivered')"
        :done="props.data.status == 'Invoiced'"
        hidden
      >
      </q-step>
    </q-stepper>
  </div>
  <q-separator />
  <div class="px-12 font-size-large q-my-md">{{ $t('shipping_details') }}</div>
  <div class="mx-12 row q-card">
    <template
      v-for="(item, index) in shippingDetails"
      :key="index + item.label"
    >
      <div :class="['row px-12 ', index % 2 === 0 ? 'even' : 'odd']">
        <div class="col-8">
          <div class="break-word">{{ $t(item.label) }}</div>
        </div>
        <div class="col-4 text-wrap">
          <div class="break-word">{{ item.value }}</div>
        </div>
      </div>
    </template>
  </div>
  <div class="px-12 row mt-15">
    <q-card class="col-6">
      <iframe
        class="col-6 no-border rounded-borders"
        :src="mapSrc"
        style="max-height: 80px"
        width="100%"
        height="80px"
      />
    </q-card>
    <div class="flex column pl-10 col-6 justify-between" style="height: 80px">
      <q-btn
        unelevated
        rounded
        color="grey-4"
        text-color="black"
        :label="$t('share')"
        @click="shareLinkClick"
      />
    </div>
  </div>
  <div class="px-12 font-size-medium text-primary q-my-md">
    {{ $t('send_me_email_with_login') }}
  </div>
  <q-separator />
  <div class="mx-12 q-card mt-15" style="padding: 12px">
    <iframe
      v-if="!skeletonLoad"
      id="preview_frame"
      :src="iframe_path"
      title="file preview"
      width="100%"
      height="900px"
    ></iframe>

    <q-skeleton
      v-else
      style="width: 100%"
      :animated="false"
      width="100%"
      height="900px"
      class="custom-skeleton"
    >
    </q-skeleton>
  </div>
</template>
<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref } from 'vue';
import { useDashboardASNOrderDetail } from '../store/index';
import { useRoute } from 'vue-router';
import { api, DOC2API_URL } from 'src/pages/APIs';
import { useImageAuth } from 'src/composables/useImageAuth';
import { isEmptyString, isUndefinedOrNull } from 'src/utils/general';
import axios from 'axios';
import { ApiExceptions } from 'src/exceptions';
import { copyToClipboard } from 'quasar';
import { useTranslate } from '@tolgee/vue';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
const step = ref<number>(1);
const props = useDashboardASNOrderDetail();
const loading = ref<boolean>(false);
const route = useRoute();
const id = ref<any>(route.params.id);
let iframe_path = ref<string>('');
let skeletonLoad = ref<boolean>(true);
const token = ref<any>('');
const shareLink = ref('');
const { t } = useTranslate();
const shippingDetails = ref<any[]>([]);
const mapSrc =
  'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d1330.4803938476741!2d11.822257!3d48.168837!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x479e755d99cb0e7f%3A0x1c5f7ea14247ec54!2sFELLOWPRO%20AG!5e0!3m2!1sde!2sde!4v1709785354741!5m2!1sde!2sde';
async function shareLinkClick() {
  if (route.fullPath.includes('/share')) {
    shareLink.value = window.location as any;
    copyToClipboard(shareLink.value).then(() => {
      notify.success(t.value('copy_to_clipboard'));
    });
  } else {
    try {
      let tokens = await props.getAsnShareToken(id.value);
      if (tokens.data.token) {
        const baseUrl = window.location.origin as any;
        shareLink.value = `${baseUrl as string}/sales_order_detail/${id.value as string}/share?token=${tokens.data.token as string}`;
        copyToClipboard(shareLink.value).then(() => {
          notify.success(t.value('copy_to_clipboard'));
        });
      }
      return;
    } catch (error) {
      logError(error);
    }
  }
}
async function getAsnDashboardOrderDataDetail(id: string) {
  try {
    loading.value = true;
    if (route.fullPath.includes('/share') && route.query.token) {
      token.value = route.query.token;
      try {
        const response = await axios.get(
          api.get_asn_share_tokens + '?token=' + token.value,
        );
        props.data = response.data.data;
        initShippingDetails();
        initSharePath(token.value);
      } catch (err) {
        logError(err);
        return;
      }
    } else {
      await props.getAsnOrderDataDetail(id);
      initShippingDetails();
      initPreview(id);
    }
  } catch (error) {
    logError(error);
  } finally {
    loading.value = false;
  }
}
async function initSharePath(token: string) {
  try {
    if (
      isUndefinedOrNull(props.data.preview_path) ||
      isEmptyString(props.data.preview_path)
    ) {
      return;
    }
    try {
      skeletonLoad.value = true;
      const response = await axios.get(
        `${DOC2API_URL}/resource/get_file/${props.data.customer_po}?path=${props.data.preview_path}&download=false&token=${token}`,
        {
          responseType: 'blob',
        },
      );

      if (response.headers['content-type'] == 'application/json') {
        // if the file is not exist try to get it again after 5 seconds
        return setTimeout(function () {
          setPreviewPath();
        }, 5000);
      }
      const url = response.config.url as string;
      iframe_path.value = url;
      skeletonLoad.value = false;
    } catch (e) {
      logError(e);
    } finally {
    }
  } catch (error) {
    logError(error);
  }
}
async function setPreviewPath() {
  try {
    if (
      isUndefinedOrNull(props.data.preview_path) ||
      isEmptyString(props.data.preview_path)
    ) {
      return;
    }

    const auth_token_store = useAuthTokenStore();
    await auth_token_store.getTokenQueryParam();
    const { tokenQueryParam } = auth_token_store;

    try {
      skeletonLoad.value = true;
      const response = await axios.get(
        `${DOC2API_URL}/resource/get_file/${props.data.customer_po}?path=${props.data.preview_path}&download=false&${tokenQueryParam}`,
        {
          responseType: 'blob',
        },
      );

      if (response.headers['content-type'] == 'application/json') {
        // if the file is not exist try to get it again after 5 seconds
        return setTimeout(function () {
          setPreviewPath();
        }, 5000);
      }
      const url = response.config.url as string;
      iframe_path.value = url;
      skeletonLoad.value = false;
    } catch (e) {
      logError(e);
    } finally {
    }
  } catch (error) {
    logError(error);
  } finally {
  }
}
async function initPreview(id: any) {
  try {
    if (
      !isUndefinedOrNull(props.data.preview_path) &&
      !isEmptyString(props.data.preview_path)
    ) {
      setPreviewPath();
      return;
    }

    await props.getAsnPreview(id);
    setPreviewPath();
  } catch (error: any) {
    const msg = ApiExceptions.getErrorMessage(error);
    const errorFrame = document.getElementById(
      'preview_frame',
    ) as HTMLIFrameElement;
    const errorDoc = errorFrame.contentDocument;
    if (errorDoc) {
      errorDoc.write('<h1>Error</h1><p>Oops!  ' + msg + '.</p>');
      errorDoc.close();
    }
    logError(error);
  } finally {
  }
}
function initShippingDetails() {
  shippingDetails.value = [
    {
      label: 'customer_name',
      value: props.data.customer_name,
    },
    {
      label: 'customer_number',
      value: props.data.customer_number,
    },
    {
      label: 'advance_ship_notice',
      value: props.data.customer_order_number,
    },
    {
      label: 'line_status',
      value: props.data.line_status,
    },
    {
      label: 'order_date',
      value: new Date(props.data.order_date).toLocaleDateString('en-US'),
    },
    {
      label: 'items_quantity',
      value: props.data.ordered_quantity,
    },
    {
      label: 'method_of_shipment',
      value: props.data.otr || props.data.cpu,
    },
    {
      label: 'promised_delivery_date',
      value: new Date(props.data.promised_delivery_date).toLocaleDateString(
        'en-US',
      ),
    },
    {
      label: 'requested_delivery_date',
      value: new Date(props.data.requested_delivery_date).toLocaleDateString(
        'en-US',
      ),
    },
    {
      label: 'shipped_quantity',
      value: props.data.shipped_quantity,
    },
    {
      label: 'warehouse_name',
      value: props.data.warehouse_name,
    },
    {
      label: 'sales_person_name',
      value: props.data.sales_person_name,
    },
    {
      label: 'warehouse_number',
      value: props.data.whs,
    },
  ];
}
getAsnDashboardOrderDataDetail(id.value);
</script>

